12	import { IAgent, IAgentAttachment, IAuthenticateParams, IAuthenticateResult, IResourceMetadata } from '../common/agentService.js';
13	import { ISessionDataService } from '../common/sessionDataService.js';
14	import { ActionType, ISessionAction } from '../common/state/sessionActions.js';
15	import { AhpErrorCodes, AHP_PROVIDER_NOT_FOUND, ContentEncoding, IBrowseDirectoryResult, ICreateSessionParams, IDirectoryEntry, IFetchContentResult, ProtocolError } from '../common/state/sessionProtocol.js';
