7	import { Disposable } from '../../../base/common/lifecycle.js';
8	import { ILogService } from '../../log/common/log.js';
9	import { ActionType, NotificationType, IActionEnvelope, IActionOrigin, INotification, ISessionAction, IRootAction, IStateAction, isRootAction, isSessionAction } from '../common/state/sessionActions.js';
10	import type { IStateSnapshot } from '../common/state/sessionProtocol.js';
11	import { rootReducer, sessionReducer } from '../common/state/sessionReducers.js';
12	import { createRootState, createSessionState, type IRootState, type ISessionState, type ISessionSummary, type URI, ROOT_STATE_URI } from '../common/state/sessionState.js';
13	
14	/**
15	 * Server-side state manager for the sessions process protocol.
16	 *
17	 * Maintains the authoritative state tree (root + per-session), applies actions
18	 * through pure reducers, assigns monotonic sequence numbers, and emits
19	 * {@link IActionEnvelope}s for subscribed clients.
20	 */
21	export class SessionStateManager extends Disposable {
22	
23		private _serverSeq = 0;
24	
25		private _rootState: IRootState;
26		private readonly _sessionStates = new Map<string, ISessionState>();
27	
28		/** Tracks which session URI each active turn belongs to, keyed by turnId. */
29		private readonly _activeTurnToSession = new Map<string, string>();
30	
31		private readonly _onDidEmitEnvelope = this._register(new Emitter<IActionEnvelope>());
32		readonly onDidEmitEnvelope: Event<IActionEnvelope> = this._onDidEmitEnvelope.event;
33	
34		private readonly _onDidEmitNotification = this._register(new Emitter<INotification>());
35		readonly onDidEmitNotification: Event<INotification> = this._onDidEmitNotification.event;
36	
37		constructor(
38			@ILogService private readonly _logService: ILogService,
39		) {
40			super();
41			this._rootState = createRootState();
42		}
43		private readonly _log = (msg: string) => this._logService.warn(`[SessionStateManager] ${msg}`);
44	
45		get hasActiveSessions(): boolean {
46			return this._activeTurnToSession.size > 0;
47		}
48	
49		// ---- State accessors ----------------------------------------------------
50	
51		get rootState(): IRootState {
52			return this._rootState;
53		}
54	
55		getSessionState(session: URI): ISessionState | undefined {
56			return this._sessionStates.get(session);
57		}
58	
59		get serverSeq(): number {
60			return this._serverSeq;
61		}
62	
63		// ---- Snapshots ----------------------------------------------------------
64	
65		/**
66		 * Returns a state snapshot for a given resource URI.
67		 * The `fromSeq` in the snapshot is the current serverSeq at snapshot time;
68		 * the client should process subsequent envelopes with serverSeq > fromSeq.
69		 */
70		getSnapshot(resource: URI): IStateSnapshot | undefined {
71			if (resource === ROOT_STATE_URI) {
72				return {
73					resource,
74					state: this._rootState,
75					fromSeq: this._serverSeq,
76				};
77			}
78	
79			const sessionState = this._sessionStates.get(resource);
80			if (!sessionState) {
81				return undefined;
82			}
83	
84			return {
85				resource,
86				state: sessionState,
87				fromSeq: this._serverSeq,
88			};
89		}
90	
91		// ---- Session lifecycle --------------------------------------------------
92	
93		/**
94		 * Creates a new session in state with `lifecycle: 'creating'`.
95		 * Returns the initial session state.
96		 */
97		createSession(summary: ISessionSummary): ISessionState {
98			const key = summary.resource;
99			if (this._sessionStates.has(key)) {
100				this._logService.warn(`[SessionStateManager] Session already exists: ${key}`);
101				return this._sessionStates.get(key)!;
102			}
103	
104			const state = createSessionState(summary);
105			this._sessionStates.set(key, state);
106	
107			this._logService.trace(`[SessionStateManager] Created session: ${key}`);
108	
109			this._onDidEmitNotification.fire({
110				type: NotificationType.SessionAdded,
111				summary,
112			});
113	
114			return state;
115		}
116	
117		/**
118		 * Removes a session from state and emits a sessionRemoved notification.
119		 */
120		removeSession(session: URI): void {
121			const state = this._sessionStates.get(session);
122			if (!state) {
123				return;
124			}
125	
126			// Clean up active turn tracking
127			if (state.activeTurn) {
128				this._activeTurnToSession.delete(state.activeTurn.id);
129			}
130	
131			this._sessionStates.delete(session);
132			this._logService.trace(`[SessionStateManager] Removed session: ${session}`);
133	
134			this._onDidEmitNotification.fire({
135				type: NotificationType.SessionRemoved,
136				session,
137			});
138		}
139	
140		// ---- Turn tracking ------------------------------------------------------
141	
142		/**
143		 * Registers a mapping from turnId to session URI so that incoming
144		 * provider events (which carry only session URI) can be associated
145		 * with the correct active turn.
146		 */
147		getActiveTurnId(session: URI): string | undefined {
148			const state = this._sessionStates.get(session);
149			return state?.activeTurn?.id;
150		}
151	
152		// ---- Action dispatch ----------------------------------------------------
153	
154		/**
155		 * Dispatch a server-originated action (from the agent backend).
156		 * The action is applied to state via the reducer and emitted as an
157		 * envelope with no origin (server-produced).
158		 */
159		dispatchServerAction(action: IStateAction): void {
160			this._applyAndEmit(action, undefined);
161		}
162	
163		/**
164		 * Dispatch a client-originated action (write-ahead from a renderer).
165		 * The action is applied to state and emitted with the client's origin
166		 * so the originating client can reconcile.
167		 */
168		dispatchClientAction(action: ISessionAction, origin: IActionOrigin): unknown {
169			return this._applyAndEmit(action, origin);
170		}
171	
172		// ---- Internal -----------------------------------------------------------
173	
174		private _applyAndEmit(action: IStateAction, origin: IActionOrigin | undefined): unknown {
175			let resultingState: unknown = undefined;
176			// Apply to state
177			if (isRootAction(action)) {
178				this._rootState = rootReducer(this._rootState, action as IRootAction, this._log);
179				resultingState = this._rootState;
180			}
181	
182			if (isSessionAction(action)) {
183				const sessionAction = action as ISessionAction;
184				const key = sessionAction.session;
185				const state = this._sessionStates.get(key);
186				if (state) {
187					const newState = sessionReducer(state, sessionAction, this._log);
188					this._sessionStates.set(key, newState);
189	
190					// Track active turn for turn lifecycle
191					if (sessionAction.type === ActionType.SessionTurnStarted) {
192						this._activeTurnToSession.set(sessionAction.turnId, key);
193						this.dispatchServerAction({ type: ActionType.RootActiveSessionsChanged, activeSessions: this._activeTurnToSession.size });
194					} else if (
195						sessionAction.type === ActionType.SessionTurnComplete ||
196						sessionAction.type === ActionType.SessionTurnCancelled ||
197						sessionAction.type === ActionType.SessionError
198					) {
199						this._activeTurnToSession.delete(sessionAction.turnId);
200						this.dispatchServerAction({ type: ActionType.RootActiveSessionsChanged, activeSessions: this._activeTurnToSession.size });
201					}
202	
203					resultingState = newState;
204				} else {
205					this._logService.warn(`[SessionStateManager] Action for unknown session: ${key}, type=${action.type}`);
206				}
207			}
